mapper.update:
UPDATE fair_cancel_refund_targets
   SET status = 'COMPLETED'
     , updated_at = #{now}
 WHERE fair_cancel_refund_target_id = #{id}
   AND status = 'PENDING'

UPDATE fair_cancel_refund_targets
   SET status = 'FAILED'
     , last_error = #{error}
     , updated_at = #{now}
 WHERE fair_cancel_refund_target_id = #{id}
   AND status = 'PENDING'

UPDATE fair_cancel_refund_targets
   SET attempt_count = attempt_count + 1
     , last_error = #{error}
     , status = CASE WHEN attempt_count + 1 >= #{maxAttempts} THEN 'FAILED' ELSE 'PENDING' END
     , updated_at = #{now}
 WHERE fair_cancel_refund_target_id = #{id}
   AND status = 'PENDING'
